        lines.push('```mermaid');
        lines.push('graph LR');
        edges.forEach(function(e) { lines.push(e); });
        lines.push('```');
    }

    return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Tracker detection
// ---------------------------------------------------------------------------

function detectTrackerType() {
    try {
