                    try {
                        var freshTicket = tracker.getIssue(ticketKey, [solutionField]);
                        var freshFields = (freshTicket && freshTicket.fields) ? freshTicket.fields : freshTicket;
                        var rawValue = freshFields ? freshFields[solutionField] : null;
