        jira_remove_label: function() {},
        jira_get_ticket: function() { return { fields: {} }; },
        jira_update_field: function() {}
    };
    for (var k in (extraGlobals || {})) { globals[k] = extraGlobals[k]; }

    return loadModule(
        'js/writeSolutionAndLabels.js',
