function packedJsFiles() {
    if (!ROOT) {
        var top = file_list('.');
        if (typeof top === 'string') top = JSON.parse(top);
        var entries = ((top && top.entries) || []).map(function (e) {
            return String(e).replace(/\\/g, '/');
