            var abs = String(e).replace(/\\/g, '/');
            var name = abs.slice(abs.lastIndexOf('/') + 1);
            if (name.charAt(0) === '.') return;
            // file_list succeeds only on a directory — the probe tells
            // files (null/error) from subdirectories (entries), since
