        assert.equal(section.split('\n')[0], '---', 'leading delimiter');
        assert.equal(section.split('\n').pop(), '---', 'trailing delimiter');
        assert.equal(section.indexOf('| 1 | solo | r | \u2014 |') !== -1, true, 'em-dash for missing deps');
    });

