 2	function action(params) {
 3	    var ticket = params.ticket || {};
 4	    var ticketKey = ticket.key;
 5	    if (!ticketKey) {
 6	        console.error('writeContentOutput: no ticket key');
 7	        return { success: false, error: 'missing ticket key' };
 8	    }
 9	    var summary = (ticket.fields && ticket.fields.summary) || '';
10	    var initiatorId = params.initiator;
11	    var wipLabel = params.metadata && params.metadata.contextId
12	        ? params.metadata.contextId + '_wip'
13	        : null;
14	    // 1. Jira field (default behavior)
15	    if (contentOutput.isJiraFieldTarget(cfg)) {
16	        if (!cfg.field) {
17	            return { success: false, error: 'contentOutput.field is required for jira_field target' };
18	        }
19	        try {
20	            contentOutput.writeToTrackerField(ticketKey, cfg.field, content, cfg.operationType || 'replace', tracker);
21	            console.log('Updated "' + cfg.field + '" field for ' + ticketKey);
22	            result.field = cfg.field;
23	        } catch (e) {
24	            console.error('Failed to update field "' + cfg.field + '":', e);
25	            return { success: false, error: 'Field update failed: ' + e.toString() };
26	        }
27	    }
28	
29	    // 2. Confluence page
30	    if (contentOutput.isConfluenceTarget(cfg)) {
31	        try {
32	            // Post replies to inline comments BEFORE the page body is replaced —
33	            // while the comment anchors are still alive on the old content.
34	            var replies = contentOutput.publishCommentReplies(contentOutput.DEFAULT_REPLIES_FILE);
35	            result.replies = replies;
36	            if (replies.posted > 0 || replies.failed > 0) {
37	                console.log('Replied to ' + replies.posted + ' inline comment(s)' +
38	                    (replies.failed > 0 ? ', ' + replies.failed + ' failed' : ''));
39	            }
40	
41	            result.pageUrl = published.url;
42	            result.pageCreated = published.created;
43	            console.log('Published content to Confluence page ' + result.pageId + ' (' + (result.pageUrl || 'url unknown') + ')');
44	
45	            if (cfg.updateTrackerField !== false && cfg.target === 'confluence') {
46	                var linkText = result.pageUrl
47	                    ? 'Published to Confluence: ' + result.pageUrl
